137.         #[invariant]
138.         pub fn ref_counts_domain(&self) -> bool {
139.             &&& 0 < self.rc_width
140.             &&& forall |i: int| 0 <= i < self.rc_width <==> self.ref_counts.dom().contains(i)
141.         }
142. 
143.         #[invariant]
144.         pub fn exc_inv(&self) -> bool {
145.             &&& self.exc_locked <==> (self.exc_pending is Some || self.exc_guard is Some)
146.             &&& self.storage is Some <==> self.exc_guard is None
147.             &&& if let Option::Some(cur_r) = self.exc_pending {
148.                 &&& 0 <= cur_r <= self.rc_width
149.                 &&& self.exc_guard is None
150.                 &&& forall |x| self.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
151.             } else {
152.                 true
153.             }
154.         }
155. 
156.         #[invariant]
157.         pub fn shared_pending_in_range(&self) -> bool {
158.             forall |r| self.shared_pending.count(r) > 0 ==> (0 <= r < self.rc_width)
159.         }
160. 
161.         #[invariant]
162.         pub fn shared_guard_in_range(&self) -> bool {
163.             forall |x| self.shared_guard.count(x) > 0 ==> (0 <= x.0 < self.rc_width)
164.         }
165. 
166.         #[invariant]
167.         pub fn shared_inv_agree(&self) -> bool {
168.             forall |v| #[trigger] self.shared_guard.count(v) > 0 ==>
169.                 self.storage == Option::Some(v.1)
170.         }
171. 
172.         pub closed spec fn filter_r(shared_guard: Multiset<(int, T)>, r: int) -> Multiset<(int, T)> {
173.             shared_guard.filter(|val: (int, T)| val.0 == r)
174.         }
