177.         pub fn shared_counts_agree(&self) -> bool {
178.             forall |r| 0 <= r < self.rc_width ==>
179.                 #[trigger] self.ref_counts.index(r) ==
180.                     self.shared_pending.count(r) as int +
181.                         Self::filter_r(self.shared_guard, r).len() as int
182.         }
