219. struct_with_invariants!{
220.     struct RwLock<T> {
221.         inst: Tracked<DistRwLock::Instance<T>>,
222.         exc_locked: AtomicBool<_, DistRwLock::exc_locked<T>, _>,
223.         ref_counts: Vec<AtomicU64<_, DistRwLock::ref_counts<T>, _>>,
224.     }
225. 
226.     spec fn wf(&self) -> bool {
227. 
228.         predicate {
229.             &&& self.inst@.rc_width() == self.ref_counts@.len()
230. 
231.             &&& forall |i: int| (0 <= i && i < self.ref_counts@.len()) ==>
232.                 #[trigger] self.ref_counts@.index(i).well_formed()
233.                 && self.ref_counts@.index(i).constant() == (self.inst, i)
234.         }
235. 
236.         invariant on exc_locked with (inst) is (b: bool, g: DistRwLock::exc_locked<T>) {
237.             g.instance_id() == inst@.id()
238.             && g.value() == b
239.         }
240. 
241.         invariant on ref_counts with (inst)
242.             forall |i: int|
243.             where (0 <= i < self.ref_counts@.len())
244.             specifically (self.ref_counts@[i])
245.             is (v: u64, g: DistRwLock::ref_counts<T>)
246.         {
247.             g.instance_id() == inst@.id()
248.             && g.key() == i
249.             && g.value() == v as int
250.         }
251.     }
252. }
