254. impl<T> RwLock<T> {
255.     #[verifier::spinoff_prover]
256.     fn new(rc_width: usize, t: T) -> (s: Self)
257.         requires
258.             0 < rc_width,
259.         ensures
260.             s.wf(),
261.     {
262.         let tracked inst;
263.         let tracked exc_locked_token;
264.         let tracked mut ref_counts_tokens;
265.         proof {
266.             let tracked (
267.                 Tracked(inst0),
268.                 Tracked(exc_locked_token0),
269.                 Tracked(ref_counts_tokens0),
270.                 _,
271.                 _,
272.                 _,
273.                 _,
274.             ) = DistRwLock::Instance::initialize(rc_width as int, t, Option::Some(t));
275.             inst = inst0;
276.             exc_locked_token = exc_locked_token0;
277.             ref_counts_tokens = ref_counts_tokens0;
278.         }
279.         let tracked_inst: Tracked<DistRwLock::Instance<T>> = Tracked(inst.clone());
280.         let exc_locked_atomic = AtomicBool::new(
281.             Ghost(tracked_inst),
282.             false,
283.             Tracked(exc_locked_token),
284.         );
285.         let mut v: Vec<AtomicU64<(Tracked<DistRwLock::Instance<T>>, int), DistRwLock::ref_counts<T>, _>> = Vec::new();
286.         let mut i: usize = 0;
287.         assert forall|j: int|
288.             i <= j && j < rc_width implies #[trigger] ref_counts_tokens.dom().contains(j)
289.               && equal(ref_counts_tokens.index(j), 0)
290.         by {
291.             assert(ref_counts_tokens.dom().contains(j));
292.             assert(equal(ref_counts_tokens.index(j), 0));
293.         }
294.         assert(forall|j: int|
295.             #![trigger( ref_counts_tokens.dom().contains(j) )]
296.             #![trigger( ref_counts_tokens.index(j) )]
297.             i <= j && j < rc_width ==> (ref_counts_tokens.dom().contains(j)
298.               && equal(ref_counts_tokens.index(j), 0)));
299.         while i < rc_width
300.             invariant
301.                 i <= rc_width,
302.                 v@.len() == i as int,
303.                 forall|j: int|
304.                     0 <= j && j < i ==> #[trigger] v@.index(j).well_formed()
305.                       && equal(v@.index(j).constant(), (tracked_inst, j)),
306.                 tracked_inst@ == inst,
307.                 ref_counts_tokens.instance_id() == inst.id(),
308.                 forall|j: int|
309.                     #![trigger( ref_counts_tokens.dom().contains(j) )]
310.                     #![trigger( ref_counts_tokens.index(j) )]
311.                     i <= j && j < rc_width ==> (ref_counts_tokens.dom().contains(j)
312.                       && equal(ref_counts_tokens.index(j), 0)),
313.         {
314.             assert(ref_counts_tokens.dom().contains(i as int));
315.             let tracked ref_count_token = ref_counts_tokens.remove(i as int);
316.             let rc_atomic = AtomicU64::new(
317.                 Ghost((tracked_inst, i as int)),
318.                 0,
319.                 Tracked(ref_count_token),
320.             );
321.             v.push(rc_atomic);
322.             i = i + 1;
323.             assert forall|j: int|
324.                 i <= j && j < rc_width implies #[trigger] ref_counts_tokens.dom().contains(j)
325.                 && equal(ref_counts_tokens.index(j), 0)
326.             by {
327.                 assert(ref_counts_tokens.dom().contains(j));
328.                 assert(equal(ref_counts_tokens.index(j), 0));
329.             }
330.         }
331.         let s = RwLock { inst: Tracked(inst), exc_locked: exc_locked_atomic, ref_counts: v };
332.         assert(s.inst@.rc_width() == s.ref_counts@.len());
333.         s
334.     }
335. }
