         #[sharding(storage_option)]
         pub storage: Option<T>,

         #[sharding(constant)]
         pub val: T,
     }

     init!{
         initialize_one(t: T) {
             // Initialize with a single reader
             init storage = Option::Some(t);
             init val = t;
         }
     }

     #[invariant]
     pub fn agreement(&self) -> bool {
         self.storage == Option::Some(self.val)
     }

